	@ParameterizedTest(name = "undef={0}, empty independent RHS={1}")
	@MethodSource("siblingCases")
	void addedSiblingDoesNotInventOptionalFallback(boolean undef, boolean empty) {
		BindingSet input = graphInput();
		BindingSetAssignment sibling = undef ? values("x", FIRST, FIRST, null) : values("x", FIRST, FIRST);
		LeftJoin independent = new LeftJoin(new SingletonSet(), empty ? values("x") : values("x", SECOND));
		LeftJoin enclosing = new LeftJoin(values("o", RESULT),
				new Join(values("g", GRAPH), new Join(sibling, independent)));
		Group group = group(new Join(enclosing, pattern("anchor", ANCHOR_PRED, "av")), "x");
		Prepared prepared = prepare(group, dataset);
		int count = empty ? 2 : undef ? 1 : 0;
		int rows = empty ? 3 : 1;
		List<Map<String, Value>> expected = expected(count, rows);
		// The reference result distinguishes a true incompatible row from invented unmatched x=FIRST rows.
		assertThat(drain(prepared.reference(), input)).containsExactlyElementsOf(expected);
		assertThat(drain(prepared.unobserved(), input)).containsExactlyElementsOf(expected);
		assertThat(drain(prepared.selected(), input)).containsExactlyElementsOf(expected);
		Entry entry = prepared.onlyEntry();
		assertAuthenticEntry(prepared, entry);
		assertWholeSetRefused(entry);
		long nativeCalls = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"));
		if (nativeCalls == 0L) {
			assertThat(entry.guard()).as("unproved added-input law refuses before native Group opens").isNotBlank();
			assertThat(group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.contains("genericFallback(" + entry.guard() + ")");
			assertThat(group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN)).isNull();
		} else {
			assertDirect(prepared);
		}
	}

	private static Stream<Arguments> siblingCases() {
		return Stream.of(Arguments.of(false, false), Arguments.of(true, false), Arguments.of(true, true));
	}

