	@Test
	void directGroupTelemetryReportsTheGateAtItsOriginalChainDepth() {
		LeftJoin optional = new LeftJoin(values("o", FIRST),
				new Join(values("g", GRAPH), values("result", RESULT)));
		Filter gate = new Filter(optional, new Bound(Var.of("result")));
		Group group = group(new Join(gate, pattern("anchor", ANCHOR_PRED, "av")), "result");
		Prepared prepared = prepare(group, dataset);
		BindingSet supplied = graphInput();
		assertThat(drain(prepared.reference(), supplied)).containsExactlyElementsOf(expected(1, 1));
		assertThat(drain(prepared.unobserved(), supplied)).containsExactlyElementsOf(expected(1, 1));
		assertThat(drain(prepared.selected(), supplied)).containsExactlyElementsOf(expected(1, 1));
		assertDirect(prepared);

		NativeGroupStep step = (NativeGroupStep) prepared.onlyEntry().step();
		assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
		Integer resultSlot = step.layout.slot("result");
		assertThat(resultSlot).isNotNull();
		String runtime = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
		int start = runtime.indexOf("    actualOrder:");
		int end = runtime.indexOf("\n    janino:", start);
		assertThat(start).isNotNegative();
		assertThat(end).isGreaterThan(start);
		String actualOrder = runtime.substring(start, end);
		assertThat(actualOrder).contains("0: Values(rows=1)", "1: Values(rows=1)", "2: Values(rows=1)", "3: Pattern(")
				.contains("after[2] mask=0x" + Long.toHexString(1L << resultSlot));
	}

